guidedPractice.starterCode:
import java.util.List;
import java.util.ArrayList;

public class Polymorphism {
    interface Attacker {
        void attack();
    }
    // Implement Swordsman, Archer, Mage

    public static void main(String[] args) {
        List<Attacker> party = new ArrayList<>();
        party.add(new Swordsman());
        party.add(new Archer());
        party.add(new Mage());
        for (Attacker a : party) a.attack();
    }
}

