storyBeats.code:
interface Greetable {
    String getName();
    default void greet() {
        System.out.println("Hello, I am " + getName());
    }
}
class Wizard implements Greetable {
    private String name;
    Wizard(String n) { name = n; }
    public String getName() { return name; }
}
new Wizard("Eldrin").greet(); // Hello, I am Eldrin

